// ============================================================
//  WUMMI — ZOMBIE PINBALL
//  Entwickler: BANDOS7 · Made in Deutschland
// ============================================================

const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d', { alpha: false });
const W = 375, H = 667;
const DPR = Math.min(2, window.devicePixelRatio || 1);
canvas.width = Math.round(W * DPR);
canvas.height = Math.round(H * DPR);

const TAU = Math.PI * 2;
const clamp = (v,a,b)=> v<a?a:(v>b?b:v);
const lerp = (a,b,t)=> a+(b-a)*t;
const rand = (a,b)=> a + Math.random()*(b-a);
const randi = (a,b)=> Math.floor(rand(a,b+1));
const dist = (x1,y1,x2,y2)=> Math.hypot(x2-x1,y2-y1);
const fmt = n => Math.round(n).toLocaleString('de-DE');

function roundRect(g,x,y,w,h,r){
  r = Math.min(r, w/2, h/2);
  g.beginPath();
  g.moveTo(x+r,y);
  g.arcTo(x+w,y,x+w,y+h,r);
  g.arcTo(x+w,y+h,x,y+h,r);
  g.arcTo(x,y+h,x,y,r);
  g.arcTo(x,y,x+w,y,r);
  g.closePath();
}
function cutRect(g,x,y,w,h,c){
  g.beginPath();
  g.moveTo(x+c,y);
  g.lineTo(x+w-c,y);
  g.lineTo(x+w,y+c);
  g.lineTo(x+w,y+h-c);
  g.lineTo(x+w-c,y+h);
  g.lineTo(x+c,y+h);
  g.lineTo(x,y+h-c);
  g.lineTo(x,y+c);
  g.closePath();
}
function makeCache(w,h,drawFn){
  const sc = 2;
  const c = document.createElement('canvas');
  c.width = Math.ceil(w*sc); c.height = Math.ceil(h*sc);
  const g = c.getContext('2d');
  g.scale(sc,sc);
  drawFn(g);
  return c;
}
function spaced(g,text,x,y,sp,align){
  const chars = [...text];
  let total = 0;
  for(const ch of chars) total += g.measureText(ch).width;
  total += sp * Math.max(0, chars.length-1);
  let cx = align==='center' ? x-total/2 : align==='right' ? x-total : x;
  g.textAlign = 'left';
  for(const ch of chars){
    g.fillText(ch,cx,y);
    cx += g.measureText(ch).width + sp;
  }
  return total;
}

// ---------- Speicher ----------
const store = {
  get(k,d){ try{ const v = localStorage.getItem(k); return v===null?d:JSON.parse(v); }catch(e){ return d; } },
  set(k,v){ try{ localStorage.setItem(k,JSON.stringify(v)); }catch(e){} }
};
const SCORE_KEY = 'wummi.scores.v1';
const DIFF_KEY  = 'wummi.diff.v1';
const MUTE_KEY  = 'wummi.muted.v1';

const DIFFS = {
  rek:     { key:'rek',     name:'REKRUT',  lives:5, ballR:10,  gravity:0.23, zSpeed:0.55, bumperCount:5, zombieCount:3, flipperPower:11,   mult:1.0, desc:'LEICHTE HORDE · GROSSE KUGEL' },
  agent:   { key:'agent',   name:'AGENT',   lives:3, ballR:8.5, gravity:0.26, zSpeed:0.80, bumperCount:7, zombieCount:4, flipperPower:12.5, mult:1.5, desc:'AUSGEWOGEN · STANDARD-PROTOKOLL' },
  veteran: { key:'veteran', name:'VETERAN', lives:2, ballR:7,   gravity:0.30, zSpeed:1.10, bumperCount:9, zombieCount:6, flipperPower:14,   mult:2.0, desc:'SCHNELLE HORDE · 2× PUNKTE' }
};
const G = {
  state:'menu', diff:store.get(DIFF_KEY,'agent'), t:0,
  score:0, wave:1, lives:3, best:0, rank:0,
  serving:true, charging:false, charge:0, chargeStart:0, serveAt:0,
  muted:store.get(MUTE_KEY,false),
  shake:0, slowUntil:0, combo:0, comboT:0,
  look:0, barkUntil:0, toast:'', toastUntil:0,
  banner:'', bannerSub:'', bannerUntil:0,
  respawnAt:0, glitch:0
};
if(!DIFFS[G.diff]) G.diff='agent';
const cfg = ()=> DIFFS[G.diff];

// ---------- Audio ----------
let AC = null, master = null, ambientGain = null, NOISE = null;
function ensureAudio(){
  if(AC){ if(AC.state==='suspended') AC.resume(); return; }
  try{
    const Ctor = window.AudioContext || window.webkitAudioContext;
    if(!Ctor) return;
    AC = new Ctor();
    master = AC.createGain();
    master.gain.value = G.muted ? 0 : 0.85;
    master.connect(AC.destination);
    startAmbient();
  }catch(e){ AC = null; }
}
function noiseBuf(){
  if(NOISE) return NOISE;
  const len = AC.sampleRate * 2;
  NOISE = AC.createBuffer(1, len, AC.sampleRate);
  const d = NOISE.getChannelData(0);
  for(let i=0;i<len;i++) d[i] = Math.random()*2-1;
  return NOISE;
}
function burst(dur,vol,freq,type){
  if(!AC) return;
  const t = AC.currentTime;
  const src = AC.createBufferSource();
  src.buffer = noiseBuf();
  src.loop = true;
  const f = AC.createBiquadFilter();
  f.type = type || 'lowpass';
  f.frequency.value = freq || 700;
  f.Q.value = 1;
  const g = AC.createGain();
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.001, t+dur);
  src.connect(f); f.connect(g); g.connect(master);
  src.start(t); src.stop(t+dur);
}
function beep(freq,dur,type,vol,slide){
  if(!AC) return;
  const t = AC.currentTime;
  const o = AC.createOscillator();
  const g = AC.createGain();
  o.type = type || 'square';
  o.frequency.setValueAtTime(freq,t);
  if(slide) o.frequency.exponentialRampToValueAtTime(Math.max(20,slide), t+dur);
  g.gain.setValueAtTime(vol||0.12,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g); g.connect(master);
  o.start(t); o.stop(t+dur);
}
function startAmbient(){
  if(!AC) return;
  const g = AC.createGain(); g.gain.value = 0.05; g.connect(master);
  const lp = AC.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=120;
  const o1 = AC.createOscillator(); o1.type='sine'; o1.frequency.value=47;
  const o2 = AC.createOscillator(); o2.type='sawtooth'; o2.frequency.value=54.5;
  o1.connect(lp); o2.connect(lp); lp.connect(g);
  o1.start(); o2.start();
  const lfo = AC.createOscillator(); lfo.frequency.value = 0.06;
  const lg = AC.createGain(); lg.gain.value = 0.02;
  lfo.connect(lg); lg.connect(g.gain); lfo.start();
  const src = AC.createBufferSource(); src.buffer = noiseBuf(); src.loop = true;
  const bp = AC.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=260; bp.Q.value=0.5;
  const wg = AC.createGain(); wg.gain.value=0.018;
  src.connect(bp); bp.connect(wg); wg.connect(master); src.start();
  ambientGain = g;
}
const SFX = {
  click(){ beep(420,0.06,'square',0.10,300); },
  launch(){ burst(0.28,0.20,1200,'lowpass'); beep(90,0.32,'sawtooth',0.12,320); },
  bump(){ beep(660,0.07,'square',0.10,440); burst(0.08,0.10,1600,'highpass'); },
  hit(){ burst(0.09,0.14,600,'lowpass'); beep(150,0.07,'sawtooth',0.08,90); },
  kill(){ burst(0.35,0.20,500,'lowpass'); beep(70,0.28,'sawtooth',0.13,35); },
  pickup(){ beep(620,0.09,'sine',0.13); setTimeout(()=>beep(880,0.10,'sine',0.13),80); setTimeout(()=>beep(1240,0.16,'sine',0.12),160); },
  drain(){ beep(300,0.45,'sawtooth',0.11,55); burst(0.5,0.10,300,'lowpass'); },
  wave(){ beep(440,0.16,'square',0.11); setTimeout(()=>beep(330,0.16,'square',0.11),150); setTimeout(()=>beep(550,0.32,'square',0.12),300); },
  over(){ beep(160,0.9,'sawtooth',0.14,40); setTimeout(()=>beep(90,1.4,'sine',0.12,30),200); },
  bark(){ beep(240,0.08,'square',0.14,160); setTimeout(()=>beep(190,0.12,'square',0.12,110),90); },
  flipper(){ beep(220,0.035,'square',0.05,180); }
};
function toggleMute(){
  G.muted = !G.muted;
  store.set(MUTE_KEY,G.muted);
  if(master) master.gain.value = G.muted ? 0 : 0.85;
}

// ---------- Eingabe ----------
const pointers = new Map();
function getPos(e){
  const r = canvas.getBoundingClientRect();
  return { x:(e.clientX-r.left)*(W/r.width), y:(e.clientY-r.top)*(H/r.height) };
}
canvas.addEventListener('pointerdown', e=>{
  if(e.pointerType==='mouse' && e.button!==0) return;
  e.preventDefault();
  ensureAudio();
  const p = getPos(e);
  pointers.set(e.pointerId, p);
  handleDown(p.x,p.y,e.pointerId);
});
canvas.addEventListener('pointermove', e=>{
  const p = getPos(e);
  if(pointers.has(e.pointerId)) pointers.set(e.pointerId,p);
  G.look = clamp((p.x-W/2)/120,-1,1);
});
function releasePointer(e){
  const p = pointers.get(e.pointerId);
  if(!p) return;
  pointers.delete(e.pointerId);
  handleUp(p.x,p.y,e.pointerId);
}
canvas.addEventListener('pointerup', e=>{ e.preventDefault(); releasePointer(e); });
canvas.addEventListener('pointercancel', e=>{ releasePointer(e); });
window.addEventListener('pointerup', e=>{ if(pointers.has(e.pointerId)) releasePointer(e); });
canvas.addEventListener('contextmenu', e=>e.preventDefault());

// ---------- Menü-Hintergrund (animiertes Containment-Labor) ----------
let menuBgCache=null, playBgCache=null, titleCache=null, scanPattern=null;
let menuDust=[];
function initDust(){
  menuDust=[];
  for(let i=0;i<28;i++){
    menuDust.push({x:rand(0,W),y:rand(60,H-80),s:rand(0.6,2.2),v:rand(2,9),p:rand(0,TAU)});
  }
}
function drawDust(){
  ctx.save();
  for(const d of menuDust){
    const y = d.y - ((G.t*d.v)%620);
    const yy = y < 40 ? y+620 : y;
    const a = 0.10 + 0.10*Math.sin(G.t*2+d.p);
    ctx.fillStyle = `rgba(180,220,140,${a.toFixed(3)})`;
    ctx.beginPath();
    ctx.arc(d.x + Math.sin(G.t*0.7+d.p)*6, yy, d.s, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function buildMenuBg(g){
  const bg = g.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0a120a');
  bg.addColorStop(0.45,'#0c140b');
  bg.addColorStop(1,'#040604');
  g.fillStyle = bg; g.fillRect(0,0,W,H);

  // Rückwand-Paneele
  g.strokeStyle='rgba(120,160,100,0.07)';
  g.lineWidth=1;
  for(let y=70;y<360;y+=56){
    g.beginPath(); g.moveTo(0,y); g.lineTo(W,y); g.stroke();
  }
  for(let x=0;x<W;x+=75){
    g.beginPath(); g.moveTo(x,60); g.lineTo(x,360); g.stroke();
  }
  // Nieten
  g.fillStyle='rgba(150,190,120,0.10)';
  for(let x=18;x<W;x+=75){
    for(let y=80;y<360;y+=56){
      g.beginPath(); g.arc(x,y,1.6,0,TAU); g.fill();
    }
  }

  // Deckenrohre
  g.strokeStyle='#1a2418'; g.lineWidth=9; g.lineCap='round';
  g.beginPath(); g.moveTo(-10,42); g.lineTo(W+10,42); g.stroke();
  g.strokeStyle='rgba(150,200,120,0.14)'; g.lineWidth=1.5;
  g.beginPath(); g.moveTo(-10,38); g.lineTo(W+10,38); g.stroke();
  for(let x=40;x<W;x+=90){
    g.fillStyle='#233020'; g.fillRect(x,36,10,12);
    g.fillStyle='rgba(160,210,130,0.18)'; g.fillRect(x+2,38,2,8);
  }
  // Seitenkabel
  g.strokeStyle='#162014'; g.lineWidth=6;
  g.beginPath(); g.moveTo(9,60); g.bezierCurveTo(2,180,18,300,8,420); g.stroke();
  g.beginPath(); g.moveTo(W-9,60); g.bezierCurveTo(W-2,180,W-18,300,W-8,420); g.stroke();

  // Warnschild hinten
  g.save();
  g.globalAlpha=0.10;
  g.translate(W/2,330);
  g.strokeStyle='#b8e06a'; g.lineWidth=2;
  g.beginPath(); g.arc(0,0,28,0,TAU); g.stroke();
  for(let i=0;i<3;i++){
    const a=i*TAU/3 - Math.PI/2;
    g.beginPath(); g.arc(Math.cos(a)*14,Math.sin(a)*14,9,0,TAU); g.stroke();
  }
  g.font='700 8px "Courier New",monospace'; g.textAlign='center';
  g.fillStyle='#b8e06a'; g.fillText('BIO-GEFAHR',0,48);
  g.restore();

  // Boden mit Perspektive
  g.save();
  const vy=470;
  const fg = g.createLinearGradient(0,vy,0,H);
  fg.addColorStop(0,'rgba(30,46,26,0)');
  fg.addColorStop(1,'rgba(26,40,22,0.55)');
  g.fillStyle=fg; g.fillRect(0,vy,W,H-vy);
  g.strokeStyle='rgba(140,190,100,0.10)'; g.lineWidth=1;
  for(let i=-7;i<=7;i++){
    g.beginPath(); g.moveTo(W/2+i*8,vy); g.lineTo(W/2+i*90,H+40); g.stroke();
  }
  for(let i=1;i<=7;i++){
    const t=i/7, y=vy+Math.pow(t,1.9)*(H-vy);
    g.beginPath(); g.moveTo(0,y); g.lineTo(W,y); g.stroke();
  }
  g.restore();

  // Vignette
  const vg = g.createRadialGradient(W/2,H/2,120,W/2,H/2,430);
  vg.addColorStop(0,'rgba(0,0,0,0)');
  vg.addColorStop(0.75,'rgba(0,0,0,0.35)');
  vg.addColorStop(1,'rgba(0,0,0,0.85)');
  g.fillStyle=vg; g.fillRect(0,0,W,H);
}

function drawBeacon(){
  const t=G.t;
  const bx=W-46, by=94;
  const pulse=0.5+0.5*Math.sin(t*2.1);
  const rg=ctx.createRadialGradient(bx,by,2,bx,by,80);
  rg.addColorStop(0,`rgba(255,50,40,${0.16+0.12*pulse})`);
  rg.addColorStop(1,'rgba(255,0,0,0)');
  ctx.fillStyle=rg;
  ctx.beginPath(); ctx.arc(bx,by,80,0,TAU); ctx.fill();
  ctx.fillStyle=`rgba(255,70,50,${0.55+0.4*pulse})`;
  ctx.beginPath(); ctx.arc(bx,by,3.4,0,TAU); ctx.fill();
  // rotierender Lichtkegel
  ctx.save();
  ctx.translate(bx,by);
  ctx.rotate(t*0.55);
  ctx.globalAlpha=0.045;
  ctx.fillStyle='#ff3020';
  ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(120,-40); ctx.lineTo(120,24); ctx.closePath(); ctx.fill();
  ctx.restore();
}

function drawLampFlicker(){
  const t=G.t;
  const base=0.72 + Math.sin(t*9.1)*0.02;
  let a=base;
  if(Math.sin(t*13.7)>0.985 || Math.sin(t*3.3+1.7)>0.997) a*=0.25;
  const x=W/2, y=66;
  const lg=ctx.createRadialGradient(x,y,2,x,y,150);
  lg.addColorStop(0,`rgba(200,255,170,${0.10*a})`);
  lg.addColorStop(1,'rgba(200,255,170,0)');
  ctx.fillStyle=lg;
  ctx.beginPath(); ctx.arc(x,y,150,0,TAU); ctx.fill();
  ctx.fillStyle=`rgba(225,255,195,${0.5*a})`;
  ctx.fillRect(x-46,y-2,92,2);
}

function drawFog(){
  ctx.save();
  for(let i=0;i<3;i++){
    const x = (G.t*(7+i*4) + i*170) % (W+240) - 120;
    const y = 350 + i*85 + Math.sin(G.t*0.5+i)*16;
    const rg=ctx.createRadialGradient(x,y,10,x,y,120);
    rg.addColorStop(0,'rgba(120,160,100,0.055)');
    rg.addColorStop(1,'rgba(120,160,100,0)');
    ctx.fillStyle=rg;
    ctx.beginPath(); ctx.ellipse(x,y,130,54,0,0,TAU); ctx.fill();
  }
  ctx.restore();
}

function drawScanlines(){
  if(!scanPattern){
    const c=document.createElement('canvas'); c.width=2; c.height=3;
    const g=c.getContext('2d');
    g.fillStyle='rgba(0,0,0,0.16)'; g.fillRect(0,0,2,1);
    scanPattern=ctx.createPattern(c,'repeat');
  }
  ctx.save();
  ctx.globalAlpha=0.55;
  ctx.fillStyle=scanPattern;
  ctx.fillRect(0,0,W,H);
  ctx.restore();
}

function drawMenuBackground(){
  if(menuBgCache) ctx.drawImage(menuBgCache,0,0,W,H);
  else { ctx.fillStyle='#080d07'; ctx.fillRect(0,0,W,H); }

  drawBeacon();
  drawLampFlicker();
  drawFog();

  // linke & rechte Containment-Röhre
  drawTank(24,352,74,172,0);
  drawTank(277,352,74,172,1);

  // Podest
  const py=584;
  ctx.save();
  const pg=ctx.createRadialGradient(W/2,py,8,W/2,py,140);
  pg.addColorStop(0,'rgba(130,200,90,0.16)');
  pg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=pg;
  ctx.beginPath(); ctx.ellipse(W/2,py,150,34,0,0,TAU); ctx.fill();
  ctx.fillStyle='#101a0e';
