function collideFlipper(b,f,now){
 const tipx=f.px+Math.cos(f.angle)*f.len;
 const tipy=f.py+Math.sin(f.angle)*f.len;
 const col=segCircle(f.px,f.py,tipx,tipy,b.x,b.y,b.r+2);
 if(col.hit){
   b.x+=col.nx*col.pen; b.y+=col.ny*col.pen;
   const vn=b.vx*col.nx+b.vy*col.ny;
