  // Ecken
  ctx.strokeStyle='rgba(157,255,58,0.55)';
  ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,14);ctx.moveTo(W,0);ctx.lineTo(W,14);ctx.stroke();

  // Punkte
  ctx.textAlign='left';ctx.textBaseline='alphabetic';
