function drawDecals(){
  for(const d of decals){
    const a=Math.min(1,d.life/300)*0.8;
    ctx.save();
    ctx.globalAlpha=a;
    ctx.fillStyle=d.color;
    ctx.beginPath();
    ctx.ellipse(d.x,d.y,d.r,d.r*0.62,Math.sin(d.x)*2,0,TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(d.x+d.r*0.6,d.y+d.r*0.2,d.r*0.22,0,TAU);
    ctx.fill();
    ctx.restore();
  }
